block.template:
{# Beispiel 6 · FAQ: natives <details>/<summary> – per Tastatur bedienbar, ohne JavaScript. #}
{% if title or block.editing %}<h2 class="faq__title" id="{{ block.title_id }}">{{ title }}</h2>{% endif %}
<div class="faq">
  {% for f in fragen %}
  <details class="faq__item">
    <summary class="faq__q"><span class="faq__text">{{ f.frage }}</span><span class="faq__mark" aria-hidden="true">{{ 'caret-down' | icon }}</span></summary>
    <div class="faq__a">{{ f.antwort | rich }}</div>
  </details>
  {% endfor %}
</div>

block.css:
.faq__title { margin: 0 0 1.25rem; }
.faq { display: grid; gap: .75rem; max-width: 50rem; }
.faq__item { border: 1px solid var(--cb-line); border-radius: var(--cb-radius); background: var(--cb-surface); }
.faq__q { display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: 1rem 1.25rem; font-weight: 600; list-style: none; }
.faq__q::-webkit-details-marker { display: none; }
.faq__q:hover .faq__text { text-decoration: underline; text-underline-offset: .2em; }
.faq__mark { display: inline-flex; flex: none; font-size: 1.25rem; }
.faq__item[open] .faq__mark { transform: rotate(180deg); }
.faq__a { padding: 0 1.25rem 1.1rem; }
.faq__a > :first-child { margin-top: 0; }
.faq__a > :last-child { margin-bottom: 0; }
@media (prefers-reduced-motion: no-preference) {
  .faq__mark { transition: transform .2s ease; }
}
